def build():
    s = Spec("Шаблон_перехода_к_страницам_и_экранам.xlsx", OUT)
    s.extra["author"] = WHO
    s.extra["reparse_xlookup"] = True
    s.extra["title"] = "Страницы и экраны NotaCode"
    for i, (an, obj, concl, ev, rel, sg, ui, roles, scs, dec) in enumerate(BANK):
        r = 5 + i
        s.w("Банк_выводов", f"A{r}", "F-%03d" % (i + 1))
        s.row("Банк_выводов", r, "B", [an, obj, concl, ev, rel, sg, ui, roles, scs, dec])
    for i, (role, goal, prob, val, mat, fr, cr, ch, note) in enumerate(ROLES):
        r = 5 + i
        s.w("Роли_и_сегменты", f"A{r}", "ROLE-%03d" % (i + 1))
        s.row("Роли_и_сегменты", r, "B", [role, goal, prob, val, mat, fr, cr, ch, note])
    for i, (role, stg, goal, trig, main, alt, data, res, cr, fr, cx) in enumerate(SCEN):
        r = 5 + i
        s.w("Пользовательские_сценарии", f"A{r}", "SC-%03d" % (i + 1))
        s.row("Пользовательские_сценарии", r, "B", [role, stg, goal, trig, main, alt, data, res, cr, fr, cx])
    for i, (tp, nm, purp, sc, role, stg, task, act, src, data, comp, states, errs, auth, mon, ev, status) in enumerate(UNITS):
        r = 5 + i
        s.w("Страницы_и_экраны", f"A{r}", "U-%03d" % (i + 1))
        s.row("Страницы_и_экраны", r, "B", [tp, nm, purp, sc, role, stg, task, act, src, data, comp, states, errs, auth, mon])
        s.w("Страницы_и_экраны", f"R{r}", status)
        s.w("Страницы_и_экраны", f"S{r}", ev)
    # матрица сценарий - интерфейс (по порядку единиц)
    link = [("SC-001", "U-001", 1), ("SC-001", "U-002", 2), ("SC-002", "U-002", 1), ("SC-002", "U-003", 2), ("SC-003", "U-005", 1), ("SC-003", "U-007", 2), ("SC-004", "U-007", 1),
            ("SC-004", "U-008", 2), ("SC-004", "U-013", 3), ("SC-005", "U-007", 1), ("SC-005", "U-008", 2), ("SC-006", "U-009", 1), ("SC-007", "U-010", 1), ("SC-008", "U-003", 1),
            ("SC-008", "U-006", 2), ("SC-008", "U-012", 3), ("SC-009", "U-011", 1), ("SC-010", "U-004", 1)]
    for i, (sc, u, o) in enumerate(link):
        r = 5 + i
        s.w("Матрица_сценарий_интерфейс", f"A{r}", "M-%03d" % (i + 1))
        s.row("Матрица_сценарий_интерфейс", r, "B", [sc, u, "Основной" if o == 1 else "Вспомогательный", "Обязательная" if o <= 2 else "Желательная", o])
    for i, row in enumerate(NAV):
        r = 5 + i
        s.w("Навигация_и_карта", f"A{r}", "N-%03d" % (i + 1))
        s.row("Навигация_и_карта", r, "B", list(row))
    for k, (idx, row) in enumerate(STATES.items()):
        r = 5 + k
        s.w("Состояния_и_ошибки", f"A{r}", "S-%03d" % (k + 1))
        s.w("Состояния_и_ошибки", f"B{r}", "U-%03d" % (idx + 1))
        s.row("Состояния_и_ошибки", r, "C", [v for v in row])
    for i, row in enumerate(CONTENT):
        s.row("Контент_и_данные", 5 + i, "A", list(row))
    for k, (idx, row) in enumerate(PASS.items()):
        r = 5 + k
        s.w("Паспорт_экрана", f"A{r}", "U-%03d" % (idx + 1))
        s.row("Паспорт_экрана", r, "B", list(row))
    for i, row in enumerate(PRI):
        r = 5 + i
        s.w("Приоритизация", f"A{r}", "U-%03d" % (i + 1))
        s.w("Приоритизация", f"B{r}", UNITS[i][1])
        s.w("Приоритизация", f"C{r}", UNITS[i][3])
        s.row("Приоритизация", r, "D", list(row[:5]))
        s.w("Приоритизация", f"K{r}", row[5])
        s.w("Приоритизация", f"L{r}", row[6])
    for sh, rng in (("Банк_выводов", "A5:K12"), ("Роли_и_сегменты", "A5:J9"), ("Пользовательские_сценарии", "A5:O14"), ("Страницы_и_экраны", "A5:T17"), ("Матрица_сценарий_интерфейс", "A5:I22"),
                    ("Навигация_и_карта", "A5:J19"), ("Состояния_и_ошибки", "A5:K10"), ("Контент_и_данные", "A5:I12"), ("Паспорт_экрана", "A5:O10"), ("Приоритизация", "A5:L17")):
        s.fit(sh, rng)
    j = [["Источники", "И-1", "Банк выводов из ЛР5 (стандарт страниц, тарифы), методик 6.1-6.3 и ЛР4 (опрос, Similarweb)."],
         ["Единицы", "Е-1", "13 единиц: 6 страниц сайта и 7 экранов приложения (PWA). Страница правовых документов и поддержки не вынесена: правовые документы и контакты размещаются в подвале и должны быть в первой версии (🔲 ДОСНЯТЬ: перечень документов)."],
         ["Паспорта", "П-1", "Паспорта заполнены для 6 ключевых единиц (тарифы, регистрация, оплата, редактор, экспорт, профиль); для остальных - 🔲 ДОСНЯТЬ в проектировании."],
         ["Состояния", "С-1", "Карта состояний заполнена для 6 единиц; прочерк означает, что состояние неприменимо."],
         ["Правило", "Р-2", "По формуле шаблона P1 получают 3 единицы (выбор нотации, редактор, экспорт); тарифы, регистрация и оплата - P2 или P3, но цепочка «обнаружение ценности - выбор - оплата - первый результат» требует их включения в первый выпуск: решение принимается в методике 6.5."], ["Правило", "Р-1", "Приоритет единицы - формула шаблона; оценки 1-5 экспертные. Страницы без доказательства из анализа (подсказка об ошибке, ИИ-ассистент) имеют статус «Гипотеза»."],
         ["Ограничения", "О-1", "Опрос студентов сгенерирован (ЛР4); UX-тестирование и прототипы не проводились. 🔲 ДОСНЯТЬ: прототип и проверка с пользователями."]]
    s.new_sheets.append(dict(name="Журнал_6_4", title="Журнал рабочей копии: источники, единицы, ограничения", header=["Раздел", "Код", "Содержание"], rows=j, widths=[22, 8, 150]))
    s.to_json(os.path.join(C.DATA, "spec_64.json"))
    return len(UNITS), len(SCEN)


if __name__ == "__main__":
    print(build())
